<?php
declare(strict_types=1);require dirname(__DIR__).'/includes/bootstrap.php';require_once INCLUDE_PATH.'/staffapplications.php';if(!str_ends_with((string)Database::scalar('SELECT DATABASE()'),'_test'))exit('TEST ONLY');
Settings::set('team_staff_positions',['safety_officer'=>['label'=>'Safety Officer','required'=>['license_number','license_expiry','qualification','experience_years','emergency_contact_name']]],'json','team',false);
$in=['full_name'=>'Synthetic Position Applicant','phone'=>'9876543222','cc'=>'91','role'=>'safety_officer','id_type'=>'passport','id_number'=>'P1234567','license_number'=>'DL1234567','license_expiry'=>date('Y-m-d',time()+86400*30),'qualification'=>'diploma','experience_years'=>'0','emergency_name'=>'Synthetic Contact'];
$r=StaffApps::validate($in,[],['id_front']);if(!$r['ok'])throw new RuntimeException(json_encode($r['errors']));echo "PASS custom position normalizes valid role-specific fields\n";
foreach(['license_number','license_expiry','qualification','experience_years','emergency_contact_name']as$key){$copy=$in;unset($copy[$key==='emergency_contact_name'?'emergency_name':$key]);$bad=StaffApps::validate($copy,[],['id_front']);if(!isset($bad['errors'][$key]))throw new RuntimeException('Missing required '.$key);echo 'PASS required '.$key." cannot be omitted\n";}
