if(StaffApps::find($id)['role_applied']!=='safety_officer')throw new RuntimeException('Custom position did not persist');Database::delete('staff_applications','id=:i',['i'=>$id]);echo "PASS custom position persists through existing application table\nSUCCESS 7 staff position checks\n";
